const x = $input.first().json.body || $input.first().json;
const prompt = `Create an original OpenPulse content package for a broad, curious audience. Do not invent facts or citations. Mark uncertain claims [VERIFY]. Return ONLY valid JSON with keys: research_brief (object: thesis, key_points array, claims_to_verify array, source_urls array), article_markdown (900-1200 words), youtube_script (6-8 minutes with scene cues), short_video_scripts (array of 3 scripts, each with hook, narration, visual_direction), social_posts (array of 3), discussion_question.
Topic: ${x.title || "Untitled topic"}
Editorial angle: ${x.angle || "Explain why this matters."}
Source URLs: ${JSON.stringify(x.sources || (x.link ? [x.link] : []))}`;
return [{json:{topic:x.title || "Untitled topic",prompt}}];

const raw = $input.first().json.response || "";
let content;
try { content = JSON.parse(raw); } catch (e) { content = {generation_error:"Qwen did not return valid JSON",raw}; }
return [{json:{created_at:new Date().toISOString(),status:"needs_human_review",topic:$node["Build Prompt"].json.topic,content}}];
